package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import io.circe.Json
import scala.util.Try

// ============================================================================
// TokenType
// ============================================================================

sealed abstract class TokenType(val value: String)

object TokenType {
  case object STRING     extends TokenType("string")
  case object NUMERIC    extends TokenType("numeric")
  case object TEMPORAL   extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY     extends TokenType("binary")
  case object NULL       extends TokenType("null")
}

// ============================================================================
// Token  (immutable value type)
// ============================================================================

final case class Token(
  value:     String,
  tokenType: TokenType,
  metadata:  Map[String, Any] = Map.empty
) {
  /** Returns a new Token with additional metadata entries merged in. */
  def withMetadata(pairs: (String, Any)*): [REDACTED] = metadata ++ pairs)
}

// ============================================================================
// MutableTokenBatch  (stateful, one-shot write batch)
// ============================================================================

class MutableTokenBatch {
  private var _tokens: List[Token]  = Nil
  private var _processed: Boolean   = false

  def tokens: List[Token] = _tokens

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens = _tokens :+ token
  }

  def markProcessed(): Unit = { _processed = true }
}

// ============================================================================
// Generic containers
// ============================================================================

/** Covariant read-only container — allows subtype widening. */
class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T]                     = _items
  def size: Int                             = _items.size
  def mapTokens(f: T => String): List[String] = _items.map(f).toList
}

/** Contravariant sink — safely accepts items of any supertype. */
class TokenSink[-T] {
  private var _received: List[Any] = Nil

  def receive(item: T): Unit = { _received = _received :+ item }

  def drain(): List[Any] = {
    val result = _received
    _received = Nil
    result
  }
}

/** Invariant mutable handler — requires an exact type match. */
class BivariantHandler[T](private var _value: T) {
  def get: T                    = _value
  def set(value: T): Unit       = { _value = value }
  def transform(f: T => T): T   = { _value = f(_value); _value }
}

// ============================================================================
// Tokenizable trait  (structural Protocol in Python)
// ============================================================================

/** Implemented by any type that can convert itself to a token string. */
trait Tokenizable {
  def toToken: String
}

// ============================================================================
// BaseTokenizer
// ============================================================================

abstract class BaseTokenizer[T] {
  /** Convert a single value to its Token representation. */
  def tokenize(value: T): Token

  /** Lazily tokenizes multiple values, yielding one Token at a time. */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

// ============================================================================
// StringTokenizer
// ============================================================================

class StringTokenizer(
  encoding:   String          = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): [REDACTED] TokenType.STRING)

  /** Decode raw bytes with the configured charset, then tokenize. */
  def tokenizeBytes(bytes: Array[Byte]): [REDACTED] String(bytes, encoding))
}

// ============================================================================
// NumericTokenizer
// ============================================================================

class NumericTokenizer(
  precision:     Int                = 6,
  formatOptions: Map[String, Any]   = Map.empty
) extends BaseTokenizer[Double] {

  def tokenize(value: Double): Token = {
    val str = BigDecimal.decimal(value)
      .setScale(precision, BigDecimal.RoundingMode.HALF_UP)
      .bigDecimal
      .toPlainString
    Token(str, TokenType.NUMERIC, Map("original_type" -> "Double"))
  }

  def tokenizeInt(value: Int): [REDACTED] TokenType.NUMERIC, Map("original_type" -> "Int"))

  def tokenizeBigDecimal(value: BigDecimal): Token = {
    val str = value
      .setScale(precision, BigDecimal.RoundingMode.HALF_UP)
      .bigDecimal
      .toPlainString
    Token(str, TokenType.NUMERIC, Map("original_type" -> "BigDecimal"))
  }
}

// ============================================================================
// TemporalTokenizer
// ============================================================================

class TemporalTokenizer(formatStr: Option[String] = None)
    extends BaseTokenizer[LocalDateTime] {

  private val defaultDateTimeFormat: DateTimeFormatter =
    DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val defaultDateFormat: DateTimeFormatter =
    DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: LocalDateTime): Token = {
    val fmt = formatStr.fold(defaultDateTimeFormat)(DateTimeFormatter.ofPattern)
    Token(value.format(fmt), TokenType.TEMPORAL)
  }

  def tokenizeDate(value: LocalDate): Token = {
    val fmt = formatStr.fold(defaultDateFormat)(DateTimeFormatter.ofPattern)
    Token(value.format(fmt), TokenType.TEMPORAL)
  }
}

// ============================================================================
// UniversalTokenizer  (runtime dispatch via overloading)
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer   = new StringTokenizer()
  private val numericTokenizer  = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: [REDACTED]NULL", TokenType.NULL)
  def tokenize(value: String): [REDACTED]
  def tokenize(value: Array[Byte]): [REDACTED]
  def tokenize(value: Int): [REDACTED]
  def tokenize(value: Double): [REDACTED]
  def tokenize(value: BigDecimal): [REDACTED]
  def tokenize(value: LocalDateTime): [REDACTED]
  def tokenize(value: LocalDate): [REDACTED]
  def tokenize(value: Tokenizable): [REDACTED] TokenType.STRUCTURED)

  /** Fallback for unsupported types — delegates to toString. */
  def tokenizeAny(value: Any): [REDACTED] TokenType.STRING, Map("fallback" -> true))
}

// ============================================================================
// TokenRegistry
// ============================================================================

class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: List[T => Option[Token]]       = Nil

  def register(key: String, container: TokenContainer[T]): Unit =
    registry = registry.updated(key, container)

  def addHandler(handler: T => Option[Token]): Unit =
    handlers = handlers :+ handler

  /** For each item in the named container, tries handlers in registration
   *  order and returns the first successful result, or None if no handler
   *  matched.
   */
  def process(key: String): List[Option[Token]] =
    registry.get(key).fold(List.empty[Option[Token]]) { container =>
      container.getAll.toList.map { item =>
        handlers.iterator.flatMap(h => h(item)).nextOption()
      }
    }
}

// ============================================================================
// TokenFunctor / TokenMonad
// ============================================================================

class TokenFunctor[T](private val _value: T) {
  def get: T = _value

  def map[B](f: T => B): TokenFunctor[B]                    = new TokenFunctor(f(_value))
  def flatMap[B](f: T => TokenFunctor[B]): TokenFunctor[B]  = f(_value)
  def getOrElse[U >: T](default: => U): U                   = if (_value != null) _value else default
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  override def map[B](f: T => B): TokenMonad[B] = new TokenMonad(f(get))

  /** Applicative apply — unwrap the function inside funcWrapped and apply it. */
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get(get))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JsonTokenizer  (uses Circe)
// ============================================================================

class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /** Navigate a dot-delimited path inside a JSON value and tokenize the leaf. */
  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split('.')
    val resolved = parts.foldLeft(Option(value)) { (current, part) =>
      current.flatMap { json =>
        json.asObject.flatMap(_.apply(part))
          .orElse(
            json.asArray.flatMap { arr =>
              Try(part.toInt).toOption.flatMap(arr.lift)
            }
          )
      }
    }
    resolved.map(tokenize)
  }
}

// ============================================================================
// WhitespaceTokenizer
// ============================================================================

class WhitespaceTokenizer(
  lowercase:        Boolean        = false,
  minLength:        Int            = 0,
  maxLength:        Option[Int]    = None,
  stripPunctuation: Boolean        = false
) {
  private val punctuationChars: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    val stripped =
      if (stripPunctuation)
        word
          .dropWhile(c => punctuationChars.contains(c))
          .reverse
          .dropWhile(c => punctuationChars.contains(c))
          .reverse
      else word

    val cased     = if (lowercase) stripped.toLowerCase else stripped
    val truncated = maxLength.fold(cased)(cased.take)

    if (truncated.length < minLength || truncated.isEmpty) None
    else Some(truncated)
  }

  def tokenize(text: String): List[Token] =
    text.split("\\s+").toList.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> idx, "original" -> word))
      }
    }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var pos = 0
    text.split("\\s+").toList.flatMap { word =>
      val start = text.indexOf(word, pos)
      val end   = start + word.length
      pos = end
      processToken(word).map(processed => (processed, start, end))
    }
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// TokenizerBuilder  (immutable fluent builder)
// ============================================================================

/** Builds a tokenizer function through a fluent, immutable API.
 *
 *  Each builder method returns a new instance so the builder itself is
 *  thread-safe and composable without accidental mutation.
 */
final class TokenizerBuilder[T] private (
  normalizers: List[String => String],
  validators:  List[T => Boolean],
  metadataMap: Map[String, Any]
) {

  def withNormalizer(f: String => String): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers :+ f, validators, metadataMap)

  def withValidator(f: T => Boolean): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators :+ f, metadataMap)

  def withMetadata(pairs: (String, Any)*): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators, metadataMap ++ pairs)

  def build(): T => Token = { value =>
    validators.find(v => !v(value)).foreach { _ =>
      throw new IllegalArgumentException(s"Validation failed for $value")
    }
    val normalized = normalizers.foldLeft(value.toString)((s, f) => f(s))
    Token(normalized, TokenType.STRING, metadataMap)
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] =
    new TokenizerBuilder[T](Nil, Nil, Map.empty)
}
